```yaml
name: Auto-close PRs referencing unready issues

on:
  pull_request:
    types: [opened, edited]

permissions:
  pull-requests: write
  issues: read

jobs:
  close-unready-pr:
    runs-on: ubuntu-latest
    steps:
      - name: Close unready PR
        uses: actions/github-script@v6
        with:
          script: |
            const pr = github.event.pull_request;
            const body = pr.body || '';
            const owner = pr.base.repo.owner.login;
            const repo = pr.base.repo.name;
            const pull_number = pr.number;

            // Skip if PR is not open
            if (pr.state !== 'open') {
              core.info('PR is not open, skipping.');
              return;
            }

            // Skip if PR is from a bot
            if (pr.user.type === 'Bot' || github.actor.endsWith('[bot]')) {
              core.info('PR is from a bot, skipping.');
              return;
            }

            // Check if actor is a maintainer (org member)
            let isMaintainer = false;
            try {
              await octokit.orgs.checkMembershipForUser({
                org: 'mlflow',
                username: github.actor
              });
              isMaintainer = true;
            } catch (error) {
              if (error.status !== 404) {
                core.warning(`Error checking org membership: ${error}`);
              }
            }
            if (isMaintainer) {
              core.info('PR is from a maintainer, skipping.');
              return;
            }

            // Find issue references
            const issueRefs = [];
            const issueRegex = /#(\\d+)/g;
            const urlRegex = /https:\\/\\/github\\.com\\/[^\\/]+\\/[^\\/]+\\/issues\\/(\\d+)/g;
            let match;
            while ((match = issueRegex.exec(body)) !== null) {
              issueRefs.push(match[1]);
            }
            while ((match = urlRegex.exec(body)) !== null) {
              issueRefs.push(match[1]);
            }

            // Remove duplicates
            const uniqueRefs = [...new Set(issueRefs)];

            if (uniqueRefs.length === 0) {
              core.info('No issue references found, skipping.');
              return;
            }
            if (uniqueRefs.length > 1) {
              core.info('Multiple issue references found, skipping.');
              return;
            }

            const issueNumber = uniqueRefs[0];

            // Get issue details
            const issue = await octokit.issues.get({
              owner,
              repo,
              issue_number: issueNumber
            });

            const issueCreatedAt = new Date(issue.data.created_at);
            const cutoffDate = new Date('2026-03-10T00:00:00Z');
            if (issueCreatedAt < cutoffDate) {
              core.info(`Issue #${issueNumber} created before cutoff date, skipping.`);
              return;
            }

            // Check if issue has 'ready' label
            const hasReadyLabel = issue.data.labels.some(label => label.name === 'ready');
            if (hasReadyLabel) {
              core.info(`Issue #${issueNumber} has 'ready' label, skipping.`);
              return;
            }

            // Close PR with comment
            const commentBody = `This PR references issue #${issueNumber} which is not yet marked as ready. Please add the \`ready\` label before submitting the PR.`;
            await octokit.issues.createComment({
              owner,
              repo,
              issue_number: pull_number,
              body: commentBody
            });

            await octokit.pulls.update({
              owner,
              repo,
              pull_number,
              state: 'closed'
            });

            core.info(`Closed PR #${pull_number} due to unready issue #${issueNumber}.`);
```

